const std=@import("std");const M=@import("microbes.zig");const P=@import("production.zig");const E=std.testing.expect;
fn copy(p:P.Cell)M.Cell{var m=M.initialized(p.rng);m.nutrient=p.nutrient;m.detritus=p.detritus;for(p.cohorts,0..)|c,i|inline for(std.meta.fields(P.Cohort))|f|{@field(m.cohorts[i],f.name)=@field(c,f.name);};return m;}
fn equal(m:M.Cell,p:P.Cell)!void{try E(m.rng==p.rng and m.nutrient==p.nutrient and m.detritus==p.detritus);for(p.cohorts,m.cohorts)|c,d|{try E(d.root_fraction==0);inline for(std.meta.fields(P.Cohort))|f|try std.testing.expectEqual(@field(c,f.name),@field(d,f.name));}}
fn statsEqual(m:M.Stats,p:P.Stats)!void{inline for(std.meta.fields(P.Stats))|f|try std.testing.expectEqual(@field(p,f.name),@field(m,f.name));}
test "current production seed gives no free root and has exact resources"{var p=P.initialized(41);var m=copy(p);var ps=P.Stats{};var ms=M.Stats{};try E(P.seed(&p,&ps,0.1)==M.seed(&m,&ms,0.1));try equal(m,p);try statsEqual(ms,ps);try E(!@hasField(M.Cohort,"stored_water") and !@hasField(M.Cohort,"retention_allocation"));}
test "zero root zero hydration current physiology exact across fixed environments"{for(0..2048)|i|{var p=P.initialized(i+1);p.cohorts[0]=.{.biomass=0.125,.support_mass=0.03125,.organization=0.25,.structure=0.1,.lineage=17};var m=copy(p);const env=P.Environment{.temperature=250+@as(f32,@floatFromInt(i%120)),.depth_km=([_]f32{0,0.00001,0.00015,0.0002,0.002,0.05})[i%6],.light=@as(f32,@floatFromInt(i%3)),.carbon_available=0.1,.oxygen_carbon_capacity=0.1};const me=M.Environment{.temperature=env.temperature,.depth_km=env.depth_km,.light=env.light,.carbon_available=env.carbon_available,.oxygen_carbon_capacity=env.oxygen_carbon_capacity};const dt=([_]f32{1,360,1440,86400})[i%4];const pf=P.step(&p,env,dt);const mf=M.step(&m,me,dt);try equal(m,p);inline for(std.meta.fields(P.Flux))|f|try std.testing.expectEqual(@field(pf,f.name),@field(mf,f.name));}}
test "current disabled birth wrappers exact all original fields and six draws"{for(0..512)|i|{var p=P.initialized(i+1);p.cohorts[0]=.{.biomass=0.125,.support_mass=0.03125,.organization=0.25,.lineage=17,.reproduction_credit=0.125};var m=copy(p);var pt=P.initialized(9);var mt=copy(pt);var ps=P.Stats{.next_lineage=100};var ms=M.Stats{.next_lineage=100};const a=if(i%2==0)P.propagate(&p,0,&pt,&ps)else P.reproduce(&p,0,&pt,&ps,true);const b=if(i%2==0)M.propagateWithRoot(&m,0,&mt,&ms,.{})else M.reproduceWithRoot(&m,0,&mt,&ms,true,.{});try E(a and b);try equal(m,p);try equal(mt,pt);try statsEqual(ms,ps);}}
